                  <table className="live-matrix-table" data-testid={`${panelId}-table`}>
                    <thead>
                      <tr>
                        <th>Actual \ Predicted</th>
                        {stats.labels.map((label) => <th key={label}>{label}</th>)}
                      </tr>
                    </thead>
                    <tbody>
                      {stats.labels.map((rowLabel, i) => (
                        <tr key={rowLabel}>
                          <th>{rowLabel}</th>
                          {stats.labels.map((colLabel, j) => (
                            <td
                              key={colLabel}
